def circ(cx, cy, r):
    return f'M{cx - r} {cy} A{r} {r} 0 1 0 {cx + r} {cy} A{r} {r} 0 1 0 {cx - r} {cy}'

def rect(x, y, w, h):
    return f'M{x} {y} L{x + w} {y} L{x + w} {y + h} L{x} {y + h} Z'

